def imagen(nombre):
    """Devuelve la imagen incluida en el código como imagen PIL."""
    return Image.open(io.BytesIO(base64.b64decode(_DATOS[nombre])))


def imagen_guia(nombre):
    """Tu foto (assets/mi_<nombre>.jpg|jpeg|png) si existe; si no, la ilustración incluida."""
    for ext in ("jpg", "jpeg", "png"):
        ruta = _CARPETA / f"mi_{nombre}.{ext}"
        if ruta.exists():
            try:
                return Image.open(ruta), True
            except Exception:
                break
    return imagen(nombre), False
